import { useCallback, useEffect, useState } from "react";
//#region src/usePlatform/index.ts
function getPlatform(userAgent) {
	if (/iPad|iPhone|iPod|ios/i.test(userAgent)) return "ios";
	else if (/android/i.test(userAgent)) return "android";
	else return "unknown";
}
const usePlatform = ({ userAgent } = { userAgent: "" }) => {
	const [ua, setUa] = useState(userAgent || "");
	const [platform, setPlatform] = useState(() => {
		if (userAgent) return getPlatform(userAgent);
		return "unknown";
	});
	useEffect(() => {
		setPlatform(getPlatform(navigator.userAgent));
		setUa(navigator.userAgent);
	}, []);
	return {
		platform,
		isInMiniProgram: useCallback(() => {
			return /miniprogram/i.test(ua);
		}, [ua]),
		isInWechat: useCallback(() => {
			return /micromessenger/i.test(ua);
		}, [ua]),
		isiPhoneX: useCallback(() => {
			return /iPhoneX/i.test(ua);
		}, [ua])
	};
};
//#endregion
export { usePlatform };
